import{_ as o,a0 as r,w as l,s as p,I as i,x as s,a1 as t,A as e,ao as d}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const D=JSON.parse('{"title":"arm64 服務器中的 Debian armhf 虛擬機 | LCTT x X-CMD","titleTemplate":false,"description":"arm64 服務器中的 Debian armhf 虛擬機 | LCTT (201707) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"arm64 服務器中的 Debian armhf 虛擬機 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"arm64 服務器中的 Debian armhf 虛擬機 | LCTT (201707) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201707/20170620 Debian armhf VM on arm64 server","title":"arm64 服務器中的 Debian armhf 虛擬機","tag":"201707","desc":""},"relativePath":"201707/20170620 Debian armhf VM on arm64 server.md","filePath":"[post].md"}'),m={name:"201707/20170620 Debian armhf VM on arm64 server.md"};function b(u,n,f,g,v,k){const a=r("Link");return l(),p("div",null,[n[31]||(n[31]=i("h1",{id:"arm64-服務器中的-debian-armhf-虛擬機",tabindex:"-1"},[s("arm64 服務器中的 Debian armhf 虛擬機 "),i("a",{class:"header-anchor",href:"#arm64-服務器中的-debian-armhf-虛擬機","aria-label":"Permalink to “arm64 服務器中的 Debian armhf 虛擬機”"},"​")],-1)),i("p",null,[n[2]||(n[2]=s("在 Collabora 公司，我們所做的許多工作之一就是為客户構建包括 32 位和 64 位 ARM 系統在內的各種架構的 ",-1)),t(a,{href:"https://debian.org/"},{default:e(()=>[...n[0]||(n[0]=[s("Debian",-1)])]),_:1}),n[3]||(n[3]=s(" 衍生版。就像 Debian 做的那樣，我們的 ",-1)),t(a,{href:"http://openbuildservice.org/"},{default:e(()=>[...n[1]||(n[1]=[s("OBS",-1)])]),_:1}),n[4]||(n[4]=s(" 系統建立在原生系統而不是仿真器上。",-1))]),i("p",null,[n[6]||(n[6]=s("幸運的是隨着幾年前 ARM 服務器系統的出現，為這些系統原生構建不再像以前那麼痛苦了。對於 32 位的 ARM，我們一直依賴 ",-1)),t(a,{href:"https://en.wikipedia.org/wiki/Calxeda"},{default:e(()=>[...n[5]||(n[5]=[s("Calxeda",-1)])]),_:1}),n[7]||(n[7]=s(" 刀片服務器，然而不幸的是 Calxeda 在不久前淘汰，硬件開始顯露其年齡（儘管幸運的是 Debian Stretch 還支持它，因此至少軟件還是新的）。",-1))]),n[32]||(n[32]=i("p",null,"在 64 位 ARM 方面，我們運行在基於 Gigabyte MP30-AR1 的服務器上，該服務器可以運行 32 位的 ARM 代碼（與之相反，比如基於 ThunderX 的服務器只能運行 64 位代碼）。像這樣在它們之上運行 armhf 虛擬機作為從構建服務器（build slaves）似乎是一個很好的選擇，但是設置起來可能會需要更多東西的介入。",-1)),n[33]||(n[33]=i("p",null,"第一個陷阱是 Debian 中沒有標準的 bootloader 或者 boot 固件來啓動 qemu 仿真的 “virt” 設備（我不想使用真實機器的仿真）。這也意味着在啓動時客户機內沒有任何東西會加載內核，也不會從客户機網絡引導，這意味着需要直接的內核引導。",-1)),i("p",null,[n[9]||(n[9]=s("第二個陷阱是當前的 Debian Stretch 的 armhf 內核並不支持 qemu 虛擬機所提供的通用 PCI 主機控制器，這意味着客户機中不會出現存儲器和網絡。希望這會被儘快解決（",-1)),t(a,{href:"https://bugs.debian.org/cgi-bin/bugreport.cgi?bug=864726"},{default:e(()=>[...n[8]||(n[8]=[s("Debian bug 864726",-1)])]),_:1}),n[10]||(n[10]=s("），並出現在 Stretch 更新中，那在之前需要使用 bug 報告中附帶的補丁的自定義內核，但在這篇文章中我不想進一步説。",-1))]),i("p",null,[n[12]||(n[12]=s("高興的假設我們有一個可用的內核，剩下的挑戰是很好地管理直接內核加載。或者更具體地説，如何確保主機啓動客户機通過標準 apt 工具安裝的內核，而不必在客户機/主機之間複製內核，這本質上歸結於客户機將 ",-1)),n[13]||(n[13]=i("code",null,"/boot",-1)),n[14]||(n[14]=s(" 暴露給主機。我們選擇的方案是使用 qemu 的 9pfs 支持來從主機共享一個文件夾，並將其用作客户機的 ",-1)),n[15]||(n[15]=i("code",null,"/boot",-1)),n[16]||(n[16]=s("。對於 9p 文件夾，似乎需要 “mapped” 安全模式，因為 “none” 模式對 dpkg 有問題（[Debian bug 864718] ",-1)),t(a,{href:"https://bugs.debian.org/cgi-bin/bugreport.cgi?bug=864718"},{default:e(()=>[...n[11]||(n[11]=[s("5",-1)])]),_:1}),n[17]||(n[17]=s("）。",-1))]),n[34]||(n[34]=d(`<p>由於我們使用 libvirt 作為我們的虛擬機管理器，剩下的事情就是如何將它們組合到一起。</p><p>第一步是安裝系統，基本和平常一樣。可以直接引導進入由普通的 Stretch armhf netboot 安裝程序提供的 <code>vmlinuz</code> 和 <code>initrd.gz</code>（下載到如 <code>/tmp</code> 中）。 設置整體來説很直接，會有一些小的調整：</p><ul><li><code>/srv/armhf-vm-boot</code> 設置為 9p 共享文件夾（這個應該存在，並且由 libvirt-qemu 擁有），這之後會被用於共享 <code>/boot</code>。</li><li>內核參數中在 <code>root=</code> 後面加上 VM 中的 root 分區，根據你的情況調整。</li><li>鏡像文件使用 virtio 總線，這似乎不是默認的。</li></ul><p>除了這些調整，最後的示例命令與 virt-install 手冊頁中的相似。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>virt-install --name armhf-vm --arch armv7l --memory 512 \\</span></span>
<span class="line"><span>  --disk /srv/armhf-vm.img,bus=virtio</span></span>
<span class="line"><span>  --filesystem /srv/armhf-vm-boot,virtio-boot,mode=mapped \\</span></span>
<span class="line"><span>  --boot=kernel=/tmp/vmlinuz,initrd=/tmp/initrd.gz,kernel_args=&quot;console=ttyAMA0,root=/dev/vda1&quot;</span></span></code></pre></div><p>按照通常的方式運行安裝。到最後安裝程序可能會提示它不知道如何安裝引導程序，這個沒什麼問題。只要在結束安裝和重啓之前，切換到 shell 並以某種方式將目標系統中的 <code>/boot/vmlinuz</code> 和 <code>/boot/initrd.img</code> 複製到主機中（比如 chroot 進入 <code>/target</code> 並在已安裝的系統中使用 scp）。 這是必需的，因為安裝程序不支持 9p，但是要啓動系統，需要 initramfs 以及能夠掛載根文件系統的模組，這由已安裝的 initramfs 提供。這些完成後，安裝就可以完成了。</p><p>接下來，引導已安裝的系統。調整 libvirt 配置（比如使用 virsh 編輯並調整 xml）來使用從安裝程序複製過來的內核以及 initramfs，而不只是使用它提供的。再次啓動虛擬機，它應該就能愉快地進入安裝的 Debian 系統中了。</p><p>要在客户機這一側完成，<code>/boot</code> 應該移動到共享的 9pfs 中，<code>/boot</code> 的新 fstab 條目看上去應該這樣：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>virtio-boot /boot  9p trans=virtio,version=9p2000.L,x-systemd.automount 0 0</span></span></code></pre></div><p>有了這一步，這只是將 <code>/boot</code> 中的文件混到新的文件系統裏面，並且客户機完事了（確保 <code>vmlinuz</code>/<code>initrd.img</code> 保持符號鏈接）。內核可以如常升級，並對主機可見。</p><p>這時對於主機端，有另外一個問題需要跨過，由於客户機使用 9p 映射安全模式，客户機的符號鏈接對主機而言將是普通的包含鏈接目標的文件。為了解決這個問題，我們在客户機啓動前使用 libvirt qemu 的 hook 支持來設置合適的符號鏈接。作為一個例子，下面是我們最終使用的腳本（<code>/etc/libvirt/hooks/qemu</code>）：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>vm=$1</span></span>
<span class="line"><span>action=$2</span></span>
<span class="line"><span>bootdir=/srv/\${vm}-boot</span></span>
<span class="line"><span></span></span>
<span class="line"><span>if [ \${action} != &quot;prepare&quot; ] ; then</span></span>
<span class="line"><span>  exit 0</span></span>
<span class="line"><span>fi</span></span>
<span class="line"><span></span></span>
<span class="line"><span>if [ ! -d \${bootdir} ] ; then</span></span>
<span class="line"><span>  exit 0</span></span>
<span class="line"><span>fi</span></span>
<span class="line"><span></span></span>
<span class="line"><span>ln -sf $(basename $(cat \${bootdir}/vmlinuz))  \${bootdir}/virtio-vmlinuz</span></span>
<span class="line"><span>ln -sf $(basename $(cat \${bootdir}/initrd.img))  \${bootdir}/virtio-initrd.img</span></span></code></pre></div><p>有了這個，我們可以簡單地定義 libvirt 使用 <code>/srv/\${vm}-boot/virtio-{vmlinuz,initrd.img}</code> 作為機器的內核 / <code>initramfs</code>，並且當 VM 啓動時，它會自動獲取客户機安裝的最新內核 / <code>initramfs</code>。</p><p>只有最後一個邊緣情況了，當從 VM libvirt 重啓會讓 qemu 處理它而不是重啓 qemu。如果這不幸發生的話，意味着重啓不會加載新內核。所以現在我們通過配置 libvirt 來解決這個問題，從而在重啓時停止虛擬機。由於我們通常只在升級內核（安裝）時重啓 VM，雖然這有點乏味，但這避免了重啓加載的是舊內核 / <code>initramfs</code> 而不是預期的。</p><hr>`,15)),i("p",null,[n[19]||(n[19]=s("via: ",-1)),t(a,{href:"https://www.collabora.com/news-and-blog/blog/2017/06/20/debian-armhf-vm-on-arm64-server/"},{default:e(()=>[...n[18]||(n[18]=[s("https://www.collabora.com/news-and-blog/blog/2017/06/20/debian-armhf-vm-on-arm64-server/",-1)])]),_:1})]),i("p",null,[n[23]||(n[23]=s("作者：",-1)),t(a,{href:"https://www.collabora.com/news-and-blog/blog/2017/06/20/debian-armhf-vm-on-arm64-server/"},{default:e(()=>[...n[20]||(n[20]=[s("Sjoerd Simons",-1)])]),_:1}),n[24]||(n[24]=s(" 譯者：",-1)),t(a,{href:"https://github.com/geekpi"},{default:e(()=>[...n[21]||(n[21]=[s("geekpi",-1)])]),_:1}),n[25]||(n[25]=s(" 校對：",-1)),t(a,{href:"https://github.com/wxy"},{default:e(()=>[...n[22]||(n[22]=[s("wxy",-1)])]),_:1})]),i("p",null,[n[28]||(n[28]=s("本文由 ",-1)),t(a,{href:"https://github.com/LCTT/TranslateProject"},{default:e(()=>[...n[26]||(n[26]=[s("LCTT",-1)])]),_:1}),n[29]||(n[29]=s(" 原創編譯，",-1)),t(a,{href:"https://linux.cn/"},{default:e(()=>[...n[27]||(n[27]=[s("Linux中國",-1)])]),_:1}),n[30]||(n[30]=s(" 榮譽推出",-1))])])}const x=o(m,[["render",b]]);export{D as __pageData,x as default};
